scenarios.example_code:
import { registerInstall } from '@projexlight/sdk-onprem';
const { install_id } = await registerInstall({
  customer_id, region: 'us-east-1', public_key_pem,
  deployment_kind: 'on-prem-kubernetes',
});

import { applyBundle } from '@projexlight/sdk-onprem';
const { applied, version } = await applyBundle({
  install_id, bundle_path: '/tmp/projexcloud-v3.2.bundle',
});

import { registerLocalLlm } from '@projexlight/sdk-onprem';
await registerLocalLlm({
  install_id, provider: 'vllm', endpoint: 'http://vllm-internal:8000/v1',
  model_id: 'llama-3-70b-instruct', allowed_uses: ['default','redaction-safe'],
});

import { uploadBillingReport } from '@projexlight/sdk-onprem';
const { snapshot_hash } = await uploadBillingReport({
  install_id, period: '2026-W21',
});
